package api.auth.kimdeo.utils

import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.platform.LocalDensity
import androidx.compose.ui.platform.LocalWindowInfo

enum class Orientation {
    PORTRAIT, LANDSCAPE, TABLET// TABLET_PORTRAIT, TABLET_LANDSCAPE
}

data class DeviceInfo(
    val orientation: Orientation,
    val width: Int,
    val height: Int,
)


@Composable
fun getDeviceInfo(): DeviceInfo {
    val winInfo = LocalWindowInfo.current
    val winSize = winInfo.containerSize
    val density = LocalDensity.current.density

    // Calculate dp from pixels
    val widthDp = (winSize.width / density).toInt()
    val heightDp = (winSize.height / density).toInt()

    // Determine if it's a tablet based on screen size
    val isTablet = isTablet(widthDp, heightDp)

    // Determine orientation with tablet distinction
    val orientation = if (isTablet) {
        Orientation.TABLET
    } else {
        if (winSize.width > winSize.height) {
            Orientation.LANDSCAPE
        } else {
            Orientation.PORTRAIT
        }
    }

    return DeviceInfo(
        orientation = orientation,
        width = winSize.width,
        height = winSize.height,
    )
}

private fun isTablet(widthDp: Int, heightDp: Int): Boolean {
    // Use the smallest dimension to determine if it's a tablet
    val smallestDimension = minOf(widthDp, heightDp)

    // Common tablet breakpoints (in dp):
    // - Phones: typically < 600dp smallest dimension
    // - Tablets: typically >= 600dp smallest dimension
    // - Some large phones may be borderline (like foldables)

    return smallestDimension >= 600
}


@Composable
fun rememberDeviceInfo(): DeviceInfo {
    val winInfo = LocalWindowInfo.current
    val winSize = winInfo.containerSize
    val density = LocalDensity.current.density

    // Calculate dp from pixels
    val widthDp = (winSize.width / density).toInt()
    val heightDp = (winSize.height / density).toInt()

    // Determine if it's a tablet based on screen size
    val isTablet = isTablet(widthDp, heightDp)

    // Determine orientation with tablet distinction
    val orientation = if (isTablet) {
        Orientation.TABLET
    } else {
        if (winSize.width > winSize.height) {
            Orientation.LANDSCAPE
        } else {
            Orientation.PORTRAIT
        }
    }

    return remember(orientation) {
        DeviceInfo(
            orientation = orientation,
            width = winSize.width,
            height = winSize.height,
        )
    }
}