object PlaygroundScreen : Screen {
    @OptIn(ExperimentalMaterial3Api::class)
    @Composable
    override fun Content() {
        val screenModel = rememberScreenModel { PlaygroundScreenModel() }
        val navigator = LocalNavigator.currentOrThrow
        val deviceInfo = rememberDeviceInfo()
        LaunchedEffect(screenModel.audioByteArray) {
            if (screenModel.audioByteArray != null) {
                screenModel.audioPlayerDisposable = loadHiddenAudioMetadata(
                    bytes = screenModel.audioByteArray!!,
                    mimeType = "audio/wav",
                    onReady = { interaction ->
                        screenModel.attachAudioController(interaction)
                    }
                )
            }
        }
        Scaffold(
            topBar = {
                if (screenModel.playgroundState == PlaygroundState.PLAYGROUND_SELECT) {
                    TopAppBar(
                        colors = TopAppBarDefaults.topAppBarColors(
                            containerColor = MaterialTheme.colorScheme.tertiary,
                            titleContentColor = MaterialTheme.colorScheme.onTertiary,
                            navigationIconContentColor = MaterialTheme.colorScheme.onTertiary,
                        ),
                        navigationIcon = {
                            IconButton(onClick = {
                                navigator.pop()
                            }, content = {
                                Icon(
                                    TablerIcons.ArrowLeft, null
                                )
                            })
                        },
                        title = {
                            Text(
                                "KimDeo AI Playground",
                                style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold)
                            )
                        }
                    )
                }
            },
            bottomBar = {
                if (deviceInfo.orientation == Orientation.PORTRAIT && screenModel.playgroundState == PlaygroundState.PLAYGROUND_SELECT){
                    Box(
                        Modifier.padding(PixelDensity.MEDIUM).background(MaterialTheme.colorScheme.primaryContainer),
                        contentAlignment = Alignment.Center
                    ) {
                        Box(
                            modifier = Modifier.fillMaxWidth()
                                .shimmerProgress(
                                    color = MaterialTheme.colorScheme.primary,
                                    shimmerColor = Color.Magenta,
                                    progress = screenModel.transcribeProcess.first / 100
                                ).padding(PixelDensity.LARGE),
                        )
                        Text(
                            text = screenModel.transcribeProcess.second,
                            style = MaterialTheme.typography.bodyMedium.copy(
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onPrimary
                            )
                        )
                    }
                }
            }
        ) { pv ->
            Box(
                modifier = Modifier.fillMaxSize().padding(pv),
                contentAlignment = Alignment.Center
            ) {
                DisplayPopup(
                    show = screenModel.playgroundPopup.show,
                    onDismiss = {
                        if (screenModel.playgroundPopup.isDismissible) {
                            screenModel.playgroundPopup = PopupModel()
                        }
                    },
                    content = {
                        Column(
                            Modifier.outline().padding(PixelDensity.MEDIUM).background(
                                shape = MaterialTheme.shapes.medium,
                                color = MaterialTheme.colorScheme.background
                            ),
                            verticalArrangement = Arrangement.spacedBy(PixelDensity.SMALL)
                        ) {
                            HorizontalTextIcon(
                                leadingContent = { screenModel.playgroundPopup.content() },
                                text = screenModel.playgroundPopup.title,
                                style = MaterialTheme.typography.bodyMedium.copy(fontWeight = FontWeight.SemiBold)
                            )
                            Text(
                                text = screenModel.playgroundPopup.description,
                                style = MaterialTheme.typography.bodyMedium
                            )
                        }
                    }
                )
                when (screenModel.playgroundState) {
                    PlaygroundState.PLAYGROUND_PLAYER -> {
                        VideoPlayer(
                            modifier = Modifier
                                .fillMaxSize()
                                .padding(PixelDensity.SMALL),
                            bytes = screenModel.fileByteArray!!,
                            mimeType = screenModel.platformFile?.mimeType()?.toString()
                                ?: "video/mp4",
                            onVolume = { volume ->
                                screenModel.audioController?.setVolume(volume / 10.0)
                            },
                            onBack = {
                                screenModel.onBackPressed {
                                    screenModel.playgroundState = PlaygroundState.PLAYGROUND_SELECT
//                                    navigator.navigateBack(ScreenType.VIDEOPLAYER)
                                }
                            },
                            interaction = { videoInteraction ->
                                screenModel.attachVideoController(videoInteraction)
                            },
                            onForwardClicked = {},
                            onBackwardClicked = {}
                        )
                        // 3. Isolated Reactive Event Loop tied strictly to the screen lifecycle
                        LaunchedEffect(screenModel.videoController) {
                            val controller = screenModel.videoController ?: return@LaunchedEffect
                            // Process the state stream cleanly without side-effects inside .map
                            controller.state
                                .collect { state ->
                                    val audioConfig = screenModel.audioFilePath ?: return@collect
                                    val audioState = screenModel.audioController?.state?.value
                                    if (state.isPlaying && state.currentTime != screenModel.lastSeekTime) {
                                        screenModel.lastSeekTime = state.currentTime
                                        val audioPosition =
                                            (state.currentTime - screenModel.audioFilePath!!.startTime)
                                                .coerceAtLeast(0.0)
                                        screenModel.audioController?.seek(audioPosition)
                                    }
                                    // *************************** manage pause play and load audio file path******************************************************
                                    val currentTime = state.currentTime

                                    // B. Check Start Threshold to play the audio track
                                    val targetStart = audioConfig.startTime
                                    if (audioState != null) {
                                        val hasStartedPlaying = currentTime >= targetStart
                                        val isAudioStopped = !audioState.isPlaying
                                        // Safely check if the audio track hasn't finished completely yet
                                        val isAudioAlreadyFinished =
                                            audioState.duration > 0.0 && audioState.currentTime >= audioState.duration

                                        if (hasStartedPlaying && isAudioStopped && !isAudioAlreadyFinished) {
                                            screenModel.audioController?.play()
                                        }

                                        // C. SYNC PAUSE/RESUME: Match audio playback state with video playback state
                                        if (hasStartedPlaying && !isAudioAlreadyFinished) {
                                            val videoIsPlaying = state.isPlaying

                                            if (videoIsPlaying && !audioState.isPlaying) {
                                                // Video is playing but audio is paused - resume audio
                                                screenModel.audioController?.play()
                                            } else if (!videoIsPlaying && audioState.isPlaying) {
                                                // Video is paused but audio is playing - pause audio
                                                screenModel.audioController?.pause()
                                            }
                                        }
                                    }
                                }
                        }
                    }

                    PlaygroundState.PLAYGROUND_SELECT -> {
                        when (deviceInfo.orientation) {
                            Orientation.PORTRAIT -> {
                                Column(
                                    modifier = Modifier.fillMaxWidth().padding(PixelDensity.MEDIUM).verticalScrollable(),
                                    horizontalAlignment = Alignment.CenterHorizontally,
                                    verticalArrangement = Arrangement.Center
                                ) {
                                    SelectFileCard(
                                        modifier = Modifier.fillMaxWidth()
                                            .padding(vertical = PixelDensity.EXTRA_LARGE),
                                        screenModel = screenModel
                                    )
                                    TranscribeFileCard(
                                        modifier = Modifier.fillMaxWidth()
                                            .padding(vertical = PixelDensity.EXTRA_LARGE),
                                        screenModel = screenModel,
                                        nav = navigator
                                    )
//                                    TranscribeOutput(
//                                        modifier = Modifier.fillMaxWidth()
//                                            .padding(vertical = PixelDensity.EXTRA_LARGE),
//                                        screenModel = screenModel
//                                    )
                                }
                            }

                            else -> {
                                Column(
                                    modifier = Modifier.width(
                                        PixelDensity.getPixelDensity(
                                            deviceInfo.width / 1.8
                                        )
                                    ).verticalScrollable(),
                                    horizontalAlignment = Alignment.CenterHorizontally,
                                    verticalArrangement = Arrangement.Center
                                ) {
                                    Row(horizontalArrangement = Arrangement.Center) {
                                        SelectFileCard(
                                            modifier = Modifier.padding(PixelDensity.SMALL),
                                            screenModel = screenModel
                                        )
                                        TranscribeFileCard(
                                            modifier = Modifier.padding(PixelDensity.SMALL),
                                            screenModel = screenModel,
                                            nav = navigator
                                        )
                                    }
                                    TranscribeOutput(
                                        modifier = Modifier.padding(PixelDensity.SMALL),
                                        screenModel = screenModel
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }


    @Composable
    private fun TranscribeOutput(modifier: Modifier, screenModel: PlaygroundScreenModel) {
        Column(
            modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            Text(
                "Transcription / Translation output",
                style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold)
            )
            Column(horizontalAlignment = Alignment.CenterHorizontally) {
                Box(
                    Modifier.background(MaterialTheme.colorScheme.primaryContainer),
                    contentAlignment = Alignment.Center
                ) {
                    Box(
                        modifier = Modifier.fillMaxWidth()
                            .height(PixelDensity.EXTRA_LARGE * 3)
                            .shimmerProgress(
                                color = MaterialTheme.colorScheme.primary,
                                shimmerColor = Color.Magenta,
                                progress = screenModel.transcribeProcess.first / 100
                            ),
                    )
                    Text(
                        text = screenModel.transcribeProcess.second,
                        style = MaterialTheme.typography.bodyMedium.copy(
                            fontWeight = FontWeight.Bold,
                            color = MaterialTheme.colorScheme.onPrimary
                        )
                    )
                }
            }
        }
    }

    @Composable
    private fun TranscribeFileCard(
        modifier: Modifier,
        screenModel: PlaygroundScreenModel,
        nav: Navigator
    ) {
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            var selectedKimLanguage by remember { mutableStateOf("") }
            var expandLanguage by remember { mutableStateOf(false) }
            Text(
                text = "Transcribe Video",
                style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Bold)
            )
            OutlinedButton(
                modifier = Modifier.fillMaxWidth(),
                enabled = (screenModel.fileByteArray != null) && screenModel.enableButton,
                onClick = { expandLanguage = !expandLanguage },
                content = {
                    HorizontalTextIcon(
                        leadingContent = { Icon(TablerIcons.Globe, null) },
                        text = "Select Language (${screenModel.kimLanguage})",
                        style = MaterialTheme.typography.bodyMedium,
                        trailingContent = {
                            Icon(
                                if (expandLanguage) TablerIcons.ChevronUp else TablerIcons.ChevronDown,
                                contentDescription = "expand languages"
                            )
                        }
                    )
                })
            AnimatedVisibility(expandLanguage, content = {
                SelectLanguages(
                    selectedKimLanguage,
                    kimLanguage = screenModel.kimLanguage,
                    kimLanguages = screenModel.kimLanguages,
                    onLangNalChanged = {
                        selectedKimLanguage = it
                        screenModel.checkKimLanguages(it)
                    },
                    onClear = {
                        selectedKimLanguage = ""
                        screenModel.checkKimLanguages("")
                    },
                    onSelect = {
                        screenModel.kimLanguage = it
                    }
                )
            })
            OutlinedButton(
                modifier = Modifier.fillMaxWidth(),
                enabled = (screenModel.fileByteArray != null) && screenModel.enableButton,
                onClick = { screenModel.transcribeVideo() },
                content = {
                    HorizontalTextIcon(
                        leadingContent = { Icon(TablerIcons.Stars, null) },
                        text = "Transcribe Video",
                        style = MaterialTheme.typography.bodyMedium
                    )
                })
            OutlinedButton(
                modifier = Modifier.fillMaxWidth(),
                enabled = (screenModel.fileByteArray != null) && screenModel.enableButton,
                onClick = {
                    screenModel.onWatchVideoClicked()
                },
                content = {
                    HorizontalTextIcon(
                        leadingContent = { Icon(TablerIcons.Video, null) },
                        text = "Watch Video",
                        style = MaterialTheme.typography.bodyMedium
                    )
                })
        }
    }

    @Composable
    private fun SelectFileCard(modifier: Modifier, screenModel: PlaygroundScreenModel) {
        Column(
            modifier = modifier,
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM)
        ) {
            Column(
                Modifier
                    .outline()
                    .clickable(onClick = { screenModel.getMediaFile() })
                    .padding(horizontal = PixelDensity.MEDIUM, vertical = PixelDensity.LARGE),
                verticalArrangement = Arrangement.spacedBy(PixelDensity.MEDIUM),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                var thumbnail by remember {
                    mutableStateOf<String?>(null)
                }
                if (screenModel.fileByteArray == null) {
                    Icon(
                        contentDescription = null,
                        imageVector = TablerIcons.Folder,
                        modifier = Modifier.size(PixelDensity.getPixelDensity(100))
                    )
                    Text(
                        text = "Click to choose a video file",
                        style = MaterialTheme.typography.bodyMedium
                    )
                } else {
                    LaunchedEffect(screenModel.fileByteArray) {
                        thumbnail = generateThumbnail(
                            bytes = screenModel.fileByteArray!!,
                            mimeType = screenModel.platformFile?.mimeType()?.toString()
                                ?: "video/mp4"
                        )
                    }
                    if (thumbnail != null) {
                        AsyncImage(
                            model = thumbnail,
                            contentDescription = "video thumbnail",
                            modifier = Modifier.width(PixelDensity.getPixelDensity(200))
                        )
                    } else {
                        Image(
                            contentDescription = null,
                            painter = painterResource(Res.drawable.video),
                            modifier = Modifier.width(PixelDensity.getPixelDensity(200))
                        )
                    }
                }
            }
            Text(
                "Supported formats: ${ExportVideoFormat.entries.joinToString(", ") { it.name.lowercase() }}",
                style = MaterialTheme.typography.bodyMedium
            )
        }
    }
}