    suspend fun logIn(
        email: String,
        password: String
    ): AuthUserModel<UserModel> {
        val res = authApiClient.post("$API_ROOT_PATH/authentication/login") {
//            header(HttpHeaders.Authorization, "Bearer ${payStackApi.secretKey}")
            header(HttpHeaders.ContentType, "application/json")
            setBody(mapOf("email" to email, "password" to password))
        }
        val resUser = kimJson.decodeFromString<AuthUserModel<UserModel>>(res.bodyAsText())
        return if (resUser.status) {
            PreferenceManager.saveInvokeLogin(
                InvokeLogIn(
                    shouldLogin = false,
                    token = resUser.userData?.authToken.toString(),
                    alreadyLogin = true
                )
            )
            resUser
        } else throw AuthenticationException(resUser.message)
    }

    suspend fun logOut(email: String, password: String): ResponseMessage<String?> {
        val res = apiClient.post("$API_ROOT_PATH/authentication/logout") {
