    suspend fun uploadProfileImage(
        email: String,
        bytes: ByteArray,
        mimeType: String,
        fileName: String,
//        file: PlatformFile,
        onFileUpload: (byteSent: Long, byteSize: Long?) -> Unit,
    ): ResponseMessage<UserModel> {

//        val bytes = file.readBytes()
//        val mimeType = file.mimeType()?.toString() ?: "application/octet-stream"

        val res = apiClient.submitFormWithBinaryData(
            url = "$API_ROOT_PATH/users/upload-profile-file/${email}",
            formData = formData {
                append(
                    "file",
                    bytes,
                    Headers.build {
                        append(
                            HttpHeaders.ContentDisposition,
                            "form-data; name=\"file\"; filename=\"$fileName\""
                        )
                        append(HttpHeaders.ContentType, mimeType)
                    }
                )
            },
        ) {
            val totalBytes = bytes.size.toLong()
            var lastProgress = 0L
            onUpload { bytesSentTotal, _ ->
                val progress = ((bytesSentTotal.toDouble() / totalBytes) * 100).toLong()

                if (progress != lastProgress) {
                    lastProgress = progress
                    onFileUpload(progress, totalBytes)
                }
            }
        }
        val resUser = kimJson.decodeFromString<ResponseMessage<UserModel>>(res.bodyAsText())
        return if (resUser.status) resUser
        else if (resUser.message.contains("http", ignoreCase = true)) {
            ResponseMessage(
                data = null,
                message = "An unexpected error occurred, please try again later",
                status = false
            )
        } else throw AuthenticationException(resUser.message)
    }


    suspend fun getTextFromMedia(
        email: String,
        bytes: ByteArray,
        mimeType: String,
        fileName: String,
//        platformFile: PlatformFile,
        onFileUpload: (byteSent: Long, byteSize: Long?) -> Unit,
        transcriptionConfig: TranscriptionConfig
    ): ResponseMessage<TranscribeJobModel?> {

//        val bytes = platformFile.readBytes()
//        val mimeType = platformFile.mimeType()?.toString() ?: "application/octet-stream"

        val res = apiClient.submitFormWithBinaryData(
            url = "${API_ROOT_PATH}/bg_task/get-text/$email",
            formData = formData {
                append(
                    "file_name",
                    bytes,
                    Headers.build {
                        append(
                            HttpHeaders.ContentDisposition,
                            "form-data; name=\"file\"; filename=\"$fileName\""
                        )
                        append(HttpHeaders.Authorization, BuildConfig.API_AUTH_KEY)
                    }
                )
                append("language", transcriptionConfig.languageCode ?: "en")
                append("add_word_timestamp", transcriptionConfig.addWordTimestamp)
                append("has_multilingual", transcriptionConfig.hasMultilingual)
                append(HttpHeaders.ContentLength, bytes.size.toString()) // 👈 add this

            },
            block = {
                val totalBytes = bytes.size.toLong()
                var lastProgress = 0L
                onUpload { bytesSentTotal, _ ->
                    val progress = ((bytesSentTotal.toDouble() / totalBytes) * 100).toLong()

                    if (progress != lastProgress) {
                        lastProgress = progress
                        onFileUpload(progress, totalBytes)
                    }
                }
            }
        )

        val resData =
            kimJson.decodeFromString<ResponseMessage<TranscribeJobModel?>>(res.bodyAsText())
        return if (resData.status) resData
        else if (resData.message.contains("http", ignoreCase = true)) {
            ResponseMessage(
                data = null,
                message = "An unexpected error occurred, please try again later",
                status = false
            )
        } else throw AuthenticationException(resData.message)
    }

