    suspend fun createVoicePlayer(
        email: String,
        bytes: ByteArray,
        mimeType: String,
        fileName: String,
        languageCode: String,
        onProgress: (Long) -> Unit
    ): ResponseMessage<TranscribeJobModel?> {

        val response = suspendCancellableCoroutine<String> { cont ->
            uploadFile(
                url = "${API_ROOT_PATH}/bg_task/create-voice-player/$email",
                bytes = bytes,
                fileName = fileName,
                languageCode = languageCode,
                authToken = PreferenceManager.getInvokeLogin().token,// BuildConfig.API_AUTH_KEY,
                mimeType = mimeType,

                onProgress = {
                    onProgress(it)
                },

                onComplete = {
                    cont.resume(it)
                },

                onError = {
                    Logger.e { "Error 5 $it" }
                    cont.resumeWithException(Exception(it))
                }
            )
        }
        return kimJson.decodeFromString(response)
    }


