package api.auth.kimdeo.model

enum class ExportFormat(val value: String) {
    TEXT(".txt"),
    JSON(".json"),
    CSV(".csv"),
    SUBTITLE(".srt"),
}


enum class ExportAudioFormat(val value: String) {
    MP3(".mp3"),
    WAV(".wav")
}

enum class ExportVideoFormat(val value: String) {
    MP4(".mp4"),
    MPEG(".mpeg"),
    MKV(".mkv"),
}



enum class FileType(val value: String) {
    AUDIO("Audio"),
    VIDEO("Video"),
    NONE("");

    companion object {

        private val videoExtensions =
            ExportVideoFormat.entries.map { it.value.removePrefix(".") }

        private val audioExtensions =
            ExportAudioFormat.entries.map { it.value.removePrefix(".") }

        fun getFileType(fileName: String?): FileType {
            if (fileName.isNullOrBlank()) return NONE

            val extension = fileName
                .substringAfterLast(".", "")
                .lowercase()

            return when (extension) {
                in videoExtensions -> VIDEO
                in audioExtensions -> AUDIO
                else -> NONE // 🔥 no crash
            }
        }

        fun getFileName(path: String): String {
            return path
                .substringAfterLast('/')
                .substringBeforeLast('.')
        }
    }
}