@Serializable
data class FilePathModel(
    val filePath: String?,
    val fileType: FileType?,
    val transcription: String?,
    val startTime: Double,
    val endTime: Double
)

@Serializable
enum class TranscribeType {
    VIDEO_PLAYER,
    TRANSCRIPTION,
    NONE,
}


@Serializable
enum class JobStatus {
    QUEUED,
    PROCESSING,
    COMPLETED,
    FAILED;

    companion object {
        fun getJobStatus(status: String): JobStatus {

            return when (status) {
                QUEUED.name -> QUEUED
                PROCESSING.name -> PROCESSING
                COMPLETED.name -> COMPLETED
                FAILED.name -> FAILED
                else -> FAILED
            }
        }
    }
}


@Serializable
data class FromLocalMediaModel(
    val email: String,
    val filePath: String,
    val jobId: String,
    val languageCode: String,
    val addWordTimestamp: Boolean,
    val hasMultilingual: Boolean,
    val bgVolume: Double,
)


@Serializable
sealed class JobMessage {
    @Serializable
    @SerialName("initial")
    data class Initial(val jobs: List<TranscribeJobModel>) : JobMessage()

    @Serializable
    @SerialName("update")
    data class Update(val job: TranscribeJobModel) : JobMessage()
}