package api.auth.kimdeo.model.plan


import kotlinx.serialization.SerialName
import kotlinx.serialization.Serializable

@Serializable
data class SubscriptionPayModel(
    @SerialName("data")
    val `data`: Data?,
    @SerialName("message")
    val message: String?,
    @SerialName("status")
    val status: Boolean?
) {
    @Serializable
    data class Data(
        @SerialName("data")
        val `data`: Data?,
        @SerialName("message")
        val message: String?,
        @SerialName("status")
        val status: Boolean?
    ) {
        @Serializable
        data class Data(
            @SerialName("access_code")
            val accessCode: String?,
            @SerialName("authorization_url")
            val authorizationUrl: String?,
            @SerialName("reference")
            val reference: String?
        )
    }
}