package api.auth.kimdeo.screens.auth

import androidx.compose.foundation.layout.size
import androidx.compose.material3.CircularProgressIndicator
import androidx.compose.material3.Icon
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import api.auth.kimdeo.core.PreferenceManager
import api.auth.kimdeo.core.api.ApiActions
import api.auth.kimdeo.model.KimCountry
import api.auth.kimdeo.model.PopupModel
import api.auth.kimdeo.model.user.RegistrationModel
import api.auth.kimdeo.model.user.UserToken
import api.auth.kimdeo.ui.PixelDensity
import api.auth.kimdeo.utils.isEmail
import cafe.adriel.voyager.core.model.ScreenModel
import cafe.adriel.voyager.core.model.screenModelScope
import compose.icons.TablerIcons
import compose.icons.tablericons.AlertTriangle
import compose.icons.tablericons.Check
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch


class AuthScreenModel : ScreenModel {

    var firstName by mutableStateOf("")
    var lastName by mutableStateOf("")
    var email by mutableStateOf("")
    var password by mutableStateOf("")
    var confirmPassword by mutableStateOf("")
    var isSignUp by mutableStateOf(false)
    var selectCountry by mutableStateOf<KimCountry?>(null)
    var showPassword by mutableStateOf(false)

    var showPopup by mutableStateOf(PopupModel())
    val disableKey: Boolean
        get() = !showPopup.show

    private fun validateSignUp(): Boolean {
        return firstName.isNotEmpty() &&
                lastName.isNotEmpty() &&
                email.isNotEmpty() &&
                email.isEmail() &&
                password.isNotEmpty() &&
                password.length > 5 &&
                selectCountry != null &&
                confirmPassword.isNotEmpty() &&
                confirmPassword == password// &&
//                isPolicyAccepted
    }

    private fun validateSignIn(): Boolean {
        return email.isNotEmpty() &&
                email.isEmail() &&
                password.isNotEmpty() &&
                password.length > 5
//                isPolicyAccepted
    }

    fun signInClicked(onSuccessful: () -> Unit) {
        screenModelScope.launch(Dispatchers.Default) {
            showPopup = PopupModel(
                true, "Signing In",
                "You are been signed in, this will take some time please wait",
                isDismissible = false,
                content = { CircularProgressIndicator(Modifier.size(PixelDensity.VERY_LARGE)) }
            )
            if (!validateSignIn()) {
                showPopup = PopupModel(
                    true, "Signing In",
                    "Some Fields are not properly filled. make sure your password is more that 5, and email is valid",
                    content = { Icon(TablerIcons.AlertTriangle, "Warning", tint = Color.Yellow) }
                )
                return@launch
            }
            runCatching {
                ApiActions.logIn(
                    email = email.trim(),
                    password = password.trim()
                )
            }.onSuccess { resUser ->
                PreferenceManager.saveUserToken(UserToken(email, resUser.userData!!.userId))
                showPopup = PopupModel(
                    true, "Signing In",
                    "Signing in was successful",
                    content = { Icon(TablerIcons.Check, "success", tint = Color.Green) }
                )
                onSuccessful()
            }.onFailure { error ->
                val eMessage = error.message ?: "Signing in"
                showPopup = PopupModel(
                    true,
                    if (eMessage.contains("http", ignoreCase = true)) "Sign in error" else eMessage,
                    "There was an error signing you in, please try again later",
                    content = { Icon(TablerIcons.AlertTriangle, "Error", tint = Color.Red) }
                )
            }

        }
    }

    fun signUpClicked(onSuccessful: () -> Unit) {
        screenModelScope.launch(Dispatchers.Default) {
            showPopup = PopupModel(
                true, "Registering",
                "You are been registered, this will take some time please wait",
                isDismissible = false,
                content = { CircularProgressIndicator(Modifier.size(PixelDensity.VERY_LARGE)) }
            )
            if (!validateSignUp()) {
                showPopup = PopupModel(
                    true, "Registering",
                    "Some Fields are not properly filled. make sure your password is more that 5, email is valid and country set",
                    content = { Icon(TablerIcons.AlertTriangle, "Warning", tint = Color.Yellow) }
                )
                return@launch
            }
            runCatching {
                ApiActions.registerUser(
                    RegistrationModel(
                        firstName = firstName.trim(),
                        lastName = lastName.trim(),
                        email = email.trim(),
                        password = password.trim(),
                        country = selectCountry!!
                    ),
                )
            }.onSuccess { resUser ->
                PreferenceManager.saveUserToken(UserToken(email, resUser.data!!.userId))
                showPopup = PopupModel(
                    true, "Registering",
                    "Registration was successful, you can close this popup",
                    content = { Icon(TablerIcons.Check, "success", tint = Color.Green) }
                )
                onSuccessful()
            }
                .onFailure { error ->
                    showPopup = PopupModel(
                        true, error.message ?: "Registering",
                        "There was an error registering you, please try again later",
                        content = { Icon(TablerIcons.AlertTriangle, "success", tint = Color.Red) }
                    )
                }
        }
    }
}
